python3 -c "
import json,math,statistics as st
d=json.load(open('tests/contracts/mdata.Prices/sample.json'))
R={t:[math.log(b/a) for a,b in zip(c,c[1:])] for t,c in d['closes'].items()}
rets={'base_date':d['dates'][0],'dates':d['dates'][1:],'tickers':d['tickers'],'values':{t:[round(x,10) for x in v] for t,v in R.items()}}
print(json.dumps(rets,indent=2))
rv={t:[None if i<2 else round(st.stdev(v[i-2:i])*math.sqrt(252),10) for i in range(len(v))] for t,v in rets['values'].items()}
print(json.dumps({'returns':rets,'window':2,'annualized':True,'values':rv},indent=2))
"
